A:

One simple approach, using std::tuple and sorted_pointers...
std::multiset<std::tuple<char, char>> set;
set.push_back(std::make_tuple('s', 'o'));    //    s, o
set.push_back(std::make_tuple('o', 'c'));    //    o, c
set.push_back(std::make_tuple('w', 'f'));    //    w, f
set.push_back(std::make_tuple('l', 'n')); //    l, n
set.push_back(std::make_tuple('e', 'c')); //    e, c
set.push_back(std::make_tuple('n', 'e')); //    n, e
set.push_back(std::make_tuple('f', 'r')); //    f, r

sort(set.begin(), set.end());

set<std::sorted_pointer<char, set::const_iterator>> s_ptrs;

s_ptrs.emplace_back(std::make_shared<char>(set.begin(), set.end())); 
//    s_ptrs.emplace_back(c);
s_ptrs.emplace_back(std::make_shared<char>(set.begin()+1, set.end()));    //    o, s, w, l, e, n, f, r
s_ptrs.emplace_back(std::make_shared<char>(set.begin(), set.end()+1));    //    c, o, w, f, r, e, n
